}

# -- .grad: per-atom subgradient ----------------------------------
## CVXPY SOURCE: atoms/elementwise/huber.py:100-118 (huber._grad).
## huber(x, M) is quadratic for |x| <= M and linear for |x| > M.
## Subgradient: 2 * sign(x) * min(|x|, M), elementwise diagonal.
method(.grad, Huber) <- function(x, values, ...) {
  rows <- as.integer(prod(x@args[[1L]]@shape))
  cols <- as.integer(prod(x@shape))
  v <- values[[1L]]
  M_val <- as.numeric(value(x@M))
  min_val <- pmin(abs(v), M_val)
  grad_vals <- 2 * sign(v) * min_val
  list(.elemwise_grad_to_diag(grad_vals, rows, cols))
}

#' Create a Huber loss atom
#'
#' @param x An Expression
#' @param M Numeric threshold (default 1)
#' @returns A Huber atom
#' @export
huber <- function(x, M = 1) {
  Huber(x, M)
}
